const id=location.pathname.match(/^\/g\/([a-f0-9]{32})$/)?.[1],status=document.querySelector('.present-status'),frame=document.querySelector('iframe');
async function api(path,{method='GET',body,secret}={}){const response=await fetch(path,{method,headers:{...(secret?{Authorization:'Bearer '+secret}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível abrir agora.');return data;}
const retry=document.querySelector('.present-retry'),actions=document.querySelector('.present-actions');let readyTimer,awaitingReady=false;
function failed(message,preserveContent=false){clearTimeout(readyTimer);awaitingReady=preserveContent;status.textContent=message;retry.hidden=false;actions.hidden=!preserveContent;frame.hidden=!preserveContent;document.querySelector('.present-fullscreen').hidden=preserveContent;}
function loadContent(){clearTimeout(readyTimer);awaitingReady=true;status.textContent='Carregando seu presente… Aguarde um instante.';retry.hidden=true;actions.hidden=true;document.querySelector('.present-fullscreen').hidden=false;frame.hidden=false;frame.src='/api/presents/'+id+'/content';readyTimer=setTimeout(()=>failed('Não conseguimos confirmar a abertura. Se o presente não apareceu, tente novamente ou baixe a cópia.',true),30000);}
addEventListener('message',event=>{if(event.source!==frame.contentWindow||!awaitingReady)return;if(event.data?.type==='capimimo:ready'){clearTimeout(readyTimer);awaitingReady=false;status.textContent='Seu presente está pronto. Abra, aproxime e leia no seu ritmo.';actions.hidden=false;retry.hidden=true;document.querySelector('.present-fullscreen').hidden=false;}else if(event.data?.type==='capimimo:error')failed('Não foi possível iniciar o presente. Tente novamente ou use um navegador atualizado.');});
frame.addEventListener('error',()=>failed('Não foi possível carregar o presente. Confira sua conexão e tente novamente.'));retry.addEventListener('click',()=>{if(!frame.getAttribute('src'))location.reload();else if(id)loadContent();});
async function open(){if(!id)throw Error('O endereço deste presente está incompleto.');const data=await api('/api/presents/'+id);document.querySelector('h1').textContent=data.recipient?'Um mimo para '+data.recipient+'.':'Tem um mimo para você.';document.querySelector('.test-notice').hidden=!data.test;loadContent();if(data.rsvp)document.querySelector('.access-note').textContent='Para confirmar presença, use o convite individual enviado a você. A confirmação aparece no final desta página.';document.querySelector('.present-download').href='/api/presents/'+id+'/download';document.querySelector('.present-fullscreen').addEventListener('click',async()=>{try{await frame.requestFullscreen();}catch{frame.scrollIntoView({behavior:'smooth',block:'start'});}});
 const guestId=new URLSearchParams(location.search).get('convidado'),secret=new URLSearchParams(location.hash.slice(1)).get('responder');if(data.rsvp&&/^[a-f0-9]{32}$/.test(guestId||'')&&/^[a-f0-9]{64}$/.test(secret||'')){
  const path='/api/presents/'+id+'/guests/'+guestId,guest=await api(path,{secret}),section=document.querySelector('.rsvp'),form=section.querySelector('form');section.hidden=false;section.querySelector('.guest-name').textContent='Este convite é para '+guest.name+'.';form.elements.count.max=guest.allowedCount;form.elements.count.value=guest.attendingCount||1;form.elements.status.value=guest.status==='declined'?'declined':'accepted';const update=()=>{const declined=form.elements.status.value==='declined';section.querySelector('.attending-label').hidden=declined;form.elements.count.disabled=declined;if(!declined&&!form.elements.count.checkValidity())form.elements.count.value='1';};form.elements.status.addEventListener('change',update);update();if(guest.status!=='invited')section.querySelector('.rsvp-status').textContent='Sua resposta já está salva. Você pode atualizá-la.';form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const result=await api(path,{method:'PUT',secret,body:{status:form.elements.status.value,attendingCount:form.elements.status.value==='declined'?0:Number(form.elements.count.value)}});section.querySelector('.rsvp-status').textContent=result.status==='accepted'?'Presença confirmada! Sua resposta foi recebida.':'Resposta recebida. Obrigado por avisar.';}catch(e){section.querySelector('.rsvp-status').textContent=e.message;}finally{button.disabled=false;}});
 }
}
open().catch(e=>{failed(e.message);document.querySelector('.access-note').textContent='Confira o endereço ou fale com quem enviou o mimo.';});
